// 5.1: bundles the app frame's engine script (QuickJS loader and the frame's local store) into
// src/shared/frame-engine.generated.ts. The engine binary itself is read at run time from the quickjs package
// (a production dependency), so the generated file holds only the script. `--check` fails when the file is stale.
import {build} from 'esbuild';
import {readFile,writeFile} from 'node:fs/promises';
const OUT='src/shared/frame-engine.generated.ts';
const built=await build({entryPoints:['src/frame-engine/frame-entry.ts'],bundle:true,minify:true,format:'iife',platform:'browser',target:'es2022',write:false,legalComments:'none',
 // The emscripten loader resolves its .wasm name against import.meta.url even when it is handed the bytes; nothing is fetched.
 define:{'import.meta.url':'"https://frame.invalid/engine.js"'},logLevel:'silent'});
const script=built.outputFiles[0].text.replace(/<\/script/gi,'<\\/script').replace(/<!--/g,'<\\!--');
const text=`// Generated by scripts/build-frame-engine.mjs from src/frame-engine/. Do not edit.\n/* eslint-disable */\nexport const FRAME_ENGINE_SCRIPT=${JSON.stringify(script)};\n`;
if(process.argv.includes('--check')){
 const current=await readFile(OUT,'utf8').catch(()=>'');
 if(current!==text){console.error(`${OUT} is stale: run node scripts/build-frame-engine.mjs`);process.exit(1);}
}else await writeFile(OUT,text);
